const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Boston, MA location
  const bostonPoint = ee.Geometry.Point([-71.0589, 42.3601]);

  // 2. Define date range: January 29 - February 5, 2019
  const startDate = '2019-01-29';
  const endDate = '2019-02-05';

  // 3. Load ERA5 Daily temperature data
  const era5Daily = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .filterDate(startDate, endDate)
    .select('maximum_2m_air_temperature');

  // Check if collection has data
  const collectionSize = era5Daily.size().getInfo();
  console.log(`ERA5 Daily images in period: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No ERA5 data available for this period.');
    console.log('C1');
    return;
  }

  // 4. Extract temperature values for each day at Boston location
  const tempsByDay = era5Daily.map(function(img) {
    const temp = img.sample(bostonPoint, 1000).first();
    return temp;
  });

  // 5. Get all temperature values (in Kelvin, convert to Celsius)
  const allTemps = era5Daily.reduceRegion(
    ee.Reducer.toList(),
    bostonPoint,
    1000
  ).get('maximum_2m_air_temperature').getInfo();

  if (!allTemps || allTemps.length === 0) {
    console.log('No valid temperature pixels at Boston location.');
    console.log('C2');
    return;
  }

  // Convert from Kelvin to Celsius
  const tempsCelsius = allTemps.map(t => t - 273.15);

  // 6. Find max and min temperatures
  const maxTemp = Math.max(...tempsCelsius);
  const minTemp = Math.min(...tempsCelsius);
  const tempDifference = maxTemp - minTemp;

  console.log(`Temperature readings (°C): ${tempsCelsius.length} days`);
  console.log(`Max temp: ${maxTemp.toFixed(2)}°C`);
  console.log(`Min temp: ${minTemp.toFixed(2)}°C`);
  console.log(`Temperature difference: ${tempDifference.toFixed(2)}°C`);
  console.log(`Threshold: 22°C`);

  // 7. Validate and determine answer
  if (isNaN(tempDifference) || tempDifference === null) {
    console.log('Calculation produced invalid result.');
    console.log('C3');
    return;
  }

  if (tempDifference >= 22) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
